package dev.chungjungsoo.gptmobile.data.database

import androidx.sqlite.db.SupportSQLiteDatabase

/** Additive migration; legacy preferences are imported only after Room opens successfully. */
internal object GatewayWorkDatabaseSchema {
    val tables = setOf("gateway_scopes", "gateway_conversations", "gateway_jobs", "gateway_messages", "gateway_replay_cursors", "gateway_commands", "gateway_engineering_bindings", "gateway_engineering_updates")

    fun create(db: SupportSQLiteDatabase) {
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_scopes` (`id` TEXT NOT NULL, `connectionUid` TEXT NOT NULL, `endpoint` TEXT NOT NULL, `gatewayId` TEXT NOT NULL, `principalId` TEXT NOT NULL, `identityScope` TEXT NOT NULL, `connectionState` TEXT NOT NULL, `observedAt` INTEGER NOT NULL, `catalogCursor` TEXT, `catalogHasMore` INTEGER NOT NULL, `error` TEXT, PRIMARY KEY(`id`))")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_conversations` (`id` TEXT NOT NULL, `scopeId` TEXT NOT NULL, `conversationId` TEXT NOT NULL, `localChatId` INTEGER, `profileUid` TEXT NOT NULL, `profileName` TEXT NOT NULL, `model` TEXT NOT NULL, `repository` TEXT, `branch` TEXT, `title` TEXT NOT NULL, `revision` INTEGER NOT NULL, `executionBinding` TEXT, `originalContext` TEXT, `historyComplete` INTEGER NOT NULL, `historyLimitation` TEXT, `updatedAt` INTEGER NOT NULL, `sourceSha` TEXT, `seenMessageSequence` INTEGER NOT NULL, `seenRevision` INTEGER NOT NULL, `projectionOwner` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`localChatId`) REFERENCES `chats_v2`(`chat_id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
        db.execSQL("CREATE INDEX IF NOT EXISTS `index_gateway_conversations_localChatId` ON `gateway_conversations` (`localChatId`)")
        db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS `index_gateway_conversations_scopeId_conversationId` ON `gateway_conversations` (`scopeId`,`conversationId`)")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_jobs` (`id` TEXT NOT NULL, `scopeId` TEXT NOT NULL, `jobId` TEXT NOT NULL, `conversationKey` TEXT NOT NULL, `kind` TEXT NOT NULL, `revision` INTEGER NOT NULL, `schedulingState` TEXT NOT NULL, `phase` TEXT NOT NULL, `acceptedAt` INTEGER, `finishedAt` INTEGER, `observedAt` INTEGER NOT NULL, `observedMonotonic` INTEGER NOT NULL, `clockSession` TEXT NOT NULL, `serverTime` INTEGER NOT NULL, `payload` TEXT NOT NULL, `engineeringPayload` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`conversationKey`) REFERENCES `gateway_conversations`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
        db.execSQL("CREATE INDEX IF NOT EXISTS `index_gateway_jobs_conversationKey` ON `gateway_jobs` (`conversationKey`)")
        db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS `index_gateway_jobs_scopeId_kind_jobId` ON `gateway_jobs` (`scopeId`,`kind`,`jobId`)")
        db.execSQL("CREATE INDEX IF NOT EXISTS `index_gateway_jobs_acceptedAt` ON `gateway_jobs` (`acceptedAt`)")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_messages` (`conversationKey` TEXT NOT NULL, `sequence` INTEGER NOT NULL, `messageId` TEXT NOT NULL, `jobId` TEXT NOT NULL, `role` TEXT NOT NULL, `kind` TEXT NOT NULL, `content` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `fingerprint` TEXT NOT NULL, `localMessageId` INTEGER, `logicalMessageId` TEXT NOT NULL, `partIndex` INTEGER NOT NULL, `partCount` INTEGER NOT NULL, `contentSha256` TEXT, `projectionComplete` INTEGER NOT NULL, `contentVerified` INTEGER NOT NULL, PRIMARY KEY(`conversationKey`,`sequence`), FOREIGN KEY(`conversationKey`) REFERENCES `gateway_conversations`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
        db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS `index_gateway_messages_conversationKey_messageId` ON `gateway_messages` (`conversationKey`,`messageId`)")
        db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS `index_gateway_messages_conversationKey_logicalMessageId_partIndex` ON `gateway_messages` (`conversationKey`,`logicalMessageId`,`partIndex`)")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_replay_cursors` (`conversationKey` TEXT NOT NULL, `sequence` INTEGER NOT NULL, `cursor` TEXT, `hasMore` INTEGER NOT NULL, `historyComplete` INTEGER NOT NULL, `gapBeforeSequence` INTEGER, `historyLimitation` TEXT, PRIMARY KEY(`conversationKey`), FOREIGN KEY(`conversationKey`) REFERENCES `gateway_conversations`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_commands` (`id` TEXT NOT NULL, `scopeId` TEXT NOT NULL, `conversationKey` TEXT, `localChatId` INTEGER NOT NULL, `userMessageId` INTEGER, `assistantMessageId` INTEGER, `localRunId` TEXT, `action` TEXT NOT NULL, `payloadDigest` TEXT NOT NULL, `payload` TEXT NOT NULL, `state` TEXT NOT NULL, `jobId` TEXT, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `error` TEXT, PRIMARY KEY(`id`), FOREIGN KEY(`localChatId`) REFERENCES `chats_v2`(`chat_id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
        db.execSQL("CREATE INDEX IF NOT EXISTS `index_gateway_commands_localChatId` ON `gateway_commands` (`localChatId`)")
        db.execSQL("CREATE INDEX IF NOT EXISTS `index_gateway_commands_scopeId_jobId` ON `gateway_commands` (`scopeId`,`jobId`)")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_engineering_bindings` (`requestId` TEXT NOT NULL, `scopeId` TEXT NOT NULL, `localChatId` INTEGER NOT NULL, `jobId` TEXT, `binding` TEXT NOT NULL, `syncedRevision` INTEGER NOT NULL, `seenRevision` INTEGER NOT NULL, `notifiedRevision` INTEGER NOT NULL, PRIMARY KEY(`requestId`), FOREIGN KEY(`localChatId`) REFERENCES `chats_v2`(`chat_id`) ON UPDATE NO ACTION ON DELETE CASCADE)")
        db.execSQL("CREATE INDEX IF NOT EXISTS `index_gateway_engineering_bindings_localChatId` ON `gateway_engineering_bindings` (`localChatId`)")
        db.execSQL("CREATE TABLE IF NOT EXISTS `gateway_engineering_updates` (`requestId` TEXT NOT NULL, `revision` INTEGER NOT NULL, `state` TEXT NOT NULL, `message` TEXT NOT NULL, `createdAt` REAL NOT NULL, PRIMARY KEY(`requestId`,`revision`), FOREIGN KEY(`requestId`) REFERENCES `gateway_engineering_bindings`(`requestId`) ON UPDATE NO ACTION ON DELETE CASCADE)")
    }
}
